/* Erklärt Aufgabenkürzel (K1b, R2, S1a, T3a, …) als Klartext.
   Desktop: natives title beim Hovern. Touch: antippbares Mini-Popover (kein Layoutbruch).
   Quelle: unterricht-src/_lib/kuerzel-tip.js – wird von gen_themen_data.py an themen-data.js angehängt.
   Nur wirksam, wo THEMEN_DATA geladen ist (Selbstlernseiten, nicht in den benoteten Tests). */
(function(){
"use strict";
if(window.KFTip) return;
var D = window.THEMEN_DATA || {sites:{}, sections:{}, themenNamen:{}};
var LV = {muss:"MUSS", soll:"SOLL", kann:"KANN"};
var BY = {};
Object.keys(D.sites || {}).forEach(function(k){
  ((D.sites[k] || {}).tasks || []).forEach(function(x){ BY[x[0]] = {id:x[0], lvl:x[1], th:x[2], sec:x[4] || "", k:k}; });
});
var esc = function(s){ return String(s==null?"":s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;"); };
function info(id){
  if(id == null || id === "") return null;
  var raw = String(id), key = raw;
  var m = /^[a-z]+:(.+)$/.exec(raw); if(m) key = m[1];
  return BY[key] || null;
}
function sectionTitle(t){
  var sec = ((D.sections || {})[t.k] || {})[t.sec] || "";
  var sub = (t.sec === "W" && D.themenNamen && D.themenNamen[t.th]) ? " (" + D.themenNamen[t.th] + ")" : "";
  return sec ? sec + sub : "";
}
function text(id){
  var t = info(id); if(!t) return "";
  var tit = sectionTitle(t), lv = LV[t.lvl] || String(t.lvl || "").toUpperCase(), parts = [t.id];
  if(tit) parts.push(tit); if(lv) parts.push(lv);
  return parts.join(" · ");
}
function html(id, inner){
  var t = text(id), label = inner != null ? inner : esc((info(id) || {}).id || id);
  if(!t) return label;
  return '<span class="kf-tid" title="'+esc(t)+'" data-tip="'+esc(t)+'" tabindex="0">'+label+'</span>';
}
function attrs(id){
  var t = text(id);
  return t ? ' class="kf-tid" title="'+esc(t)+'" data-tip="'+esc(t)+'" tabindex="0"' : "";
}
function wrapIds(s){
  return String(s==null?"":s).replace(/\b([A-Z]{1,3}\d+[a-z]?)\b/g, function(all, id){ return BY[id] ? html(id) : all; });
}
function el(id){
  var t = text(id); if(!t) return null;
  var s = document.createElement("span");
  s.className = "kf-tid"; s.title = t; s.setAttribute("data-tip", t); s.tabIndex = 0;
  s.textContent = (info(id) || {}).id || String(id);
  return s;
}

var CSS = ".kf-tid{cursor:help;text-decoration:underline dotted;text-underline-offset:2px}"
  + "#kfTipPop{position:fixed;z-index:100000;max-width:17rem;background:#1c3d5a;color:#fff;padding:.45rem .65rem;border-radius:8px;font:600 13px/1.35 system-ui,sans-serif;box-shadow:0 4px 18px #0006;pointer-events:none;display:none;left:0;top:0}"
  + "#kfTipPop.on{display:block}";
var pop, cur;
function ensure(){
  if(!document.getElementById("kfTipCss")){
    var st = document.createElement("style"); st.id = "kfTipCss"; st.textContent = CSS;
    (document.head || document.documentElement).appendChild(st);
  }
  if(!pop || !pop.isConnected){
    pop = document.getElementById("kfTipPop");
    if(!pop){ pop = document.createElement("div"); pop.id = "kfTipPop"; pop.setAttribute("role","tooltip"); }
    (document.body || document.documentElement).appendChild(pop);
  }
}
function hide(){ if(pop) pop.classList.remove("on"); cur = null; }
function place(node){
  var r = node.getBoundingClientRect(), pad = 8, w = pop.offsetWidth, h = pop.offsetHeight;
  var vw = window.innerWidth || 360, vh = window.innerHeight || 640;
  var left = Math.min(Math.max(pad, r.left + r.width/2 - w/2), vw - w - pad);
  var top = r.top - h - 8; if(top < pad) top = Math.min(r.bottom + 8, vh - h - pad);
  pop.style.left = Math.max(pad, left) + "px"; pop.style.top = Math.max(pad, top) + "px";
}
function show(node){
  var t = node.getAttribute("data-tip"); if(!t) return;
  ensure(); pop.textContent = t; pop.classList.add("on"); cur = node; place(node);
}
function onDoc(ev){
  var node = ev.target && ev.target.closest && ev.target.closest(".kf-tid[data-tip]");
  if(!node){ if(ev.type === "click") hide(); return; }
  if(node.closest("a, button, label, input, textarea, select")) return;
  if(ev.type === "keydown" && ev.key !== "Enter" && ev.key !== " ") return;
  if(ev.type === "keydown" || ev.type === "click"){
    ev.preventDefault(); ev.stopPropagation();
    if(cur === node && pop && pop.classList.contains("on")) hide(); else show(node);
  }
}
function bind(){
  if(window.__kfTipBound) return; window.__kfTipBound = 1;
  ensure();
  document.addEventListener("click", onDoc, true);
  document.addEventListener("keydown", onDoc, true);
  document.addEventListener("scroll", hide, true);
  window.addEventListener("resize", hide);
}
if(document.readyState === "loading") document.addEventListener("DOMContentLoaded", bind); else bind();
window.KFTip = {text:text, html:html, attrs:attrs, wrapIds:wrapIds, info:info, el:el, bind:bind, show:show, hide:hide};
})();
